function CoverCanvasElement({ elementId, element, policy, selected, editing, scale, registerNode, onSelect, onEdit, onChange, onCommit, onCancelEdit }: { elementId: string; element: CoverElement; policy: Policy; selected: boolean; editing: boolean; scale: number; registerNode: (id: string, node: HTMLElement | null) => void; onSelect: () => void; onEdit: () => void; onChange: (patch: Partial<CoverElement>, transient?: boolean) => void; onCommit: () => void; onCancelEdit: () => void }) { const setNodeRef = React.useCallback((node: HTMLElement | null) => registerNode(elementId, node), [elementId, registerNode]); const text = element.type === "text" ? element : null; const liveText = text ? text.content.kind === "binding" ? getCoverBindingValue(policy, text.content.binding) : text.content.text : ""; const style: React.CSSProperties = { position: "absolute", left: `${element.x * scale}px`, top: `${element.y * scale}px`, width: `${element.width * scale}px`, height: `${element.height * scale}px`, transform: `rotate(${element.rotation}deg)`, transformOrigin: "center", zIndex: 100 + element.zIndex, outline: selected ? "2px solid #2d9cff" : undefined, background: selected ? "rgba(45,156,255,.05)" : "transparent", cursor: element.locked ? "default" : "move", pointerEvents: "auto" }; const textStyle: React.CSSProperties = { color: text?.color, fontFamily: text?.fontFamily, fontSize: text ? `${coverPointSizeToPixels(text.fontSize, scale)}px` : undefined, fontWeight: text?.bold ? 700 : 400, fontStyle: text?.italic ? "italic" : "normal", textDecoration: text?.underline ? "underline" : "none", textAlign: text?.align, lineHeight: text?.lineHeight, letterSpacing: text ? `${coverPointSizeToPixels(text.letterSpacing, scale)}px` : undefined, whiteSpace: "pre-wrap", overflowWrap: "anywhere" }; if (editing && text?.content.kind === "literal") return <textarea ref={setNodeRef} aria-label="Edit cover text" autoFocus value={text.content.text} onChange={(event) => onChange({ content: { kind: "literal", text: event.target.value.slice(0, 5000) } }, true)} onBlur={onCommit} onKeyDown={(event) => { if (event.key === "Escape") { event.preventDefault(); onCancelEdit(); } if ((event.ctrlKey || event.metaKey) && event.key === "Enter") { event.preventDefault(); onCommit(); } }} style={{ ...style, ...textStyle, padding: 2, border: 0, resize: "none", outline: "2px solid #2d9cff", background: "rgba(255,255,255,.88)" }} onMouseDown={(event) => event.stopPropagation()} />; return <div ref={setNodeRef} role="button" tabIndex={0} aria-label={`Select ${text ? "text" : element.type === "logo" ? "company logo" : "image"}`} data-cover-element={element.id} style={style} onMouseDown={(event) => { event.stopPropagation(); onSelect(); }} onDoubleClick={(event) => { event.stopPropagation(); onEdit(); }} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onSelect(); } }}>{text ? <span className="block h-full w-full" style={textStyle}>{liveText}</span> : null}</div>; }

